CREATE TABLE IF NOT EXISTS shop_campaign (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,kind VARCHAR(20) NOT NULL,channel VARCHAR(1) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,config_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX campaign_active(status,starts_at,ends_at));
CREATE TABLE IF NOT EXISTS shop_campaign_pool(campaign_id BIGINT NOT NULL,product_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,channel VARCHAR(1) NOT NULL,held BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(campaign_id,product_id,warehouse_id));
CREATE TABLE IF NOT EXISTS shop_campaign_order(order_id BIGINT PRIMARY KEY,campaign_id BIGINT NOT NULL,member_id BIGINT NOT NULL,group_id BIGINT NULL,kind VARCHAR(20) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'reserved',snapshot_json LONGTEXT NOT NULL,items_json LONGTEXT NOT NULL,INDEX campaign_member(campaign_id,member_id,state));
CREATE TABLE IF NOT EXISTS shop_campaign_group(id BIGINT PRIMARY KEY AUTO_INCREMENT,campaign_id BIGINT NOT NULL,required_people INT NOT NULL,expires_at DATETIME NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX group_expire(status,expires_at));
